chrome.runtime.onInstalled.addListener(()=>{console.log("Ascend Chrome Extension installed."),chrome.sidePanel&&chrome.sidePanel.setPanelBehavior&&chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!0}).catch(e=>console.error("Error setting panel behavior:",e))});chrome.runtime.onStartup.addListener(()=>{chrome.sidePanel&&chrome.sidePanel.setPanelBehavior&&chrome.sidePanel.setPanelBehavior({openPanelOnActionClick:!0}).catch(e=>console.error("Error setting panel behavior on startup:",e))});
